import settings


def test_wechat_work_config_fields():
    config = settings.WECHAT_WORK_CONFIG
    assert config.get('enabled') is True
    assert 'webhook_url' in config and config['webhook_url'].startswith('http/workspace/')
    assert config.get('msg_type') in ('markdown', 'text')


def test_content_length_adjusted():
    assert settings.LEARNING_CONFIG['content_length'] == 300


def test_daily_count_adjusted():
    assert settings.LEARNING_CONFIG['daily_count'] == 2


def test_schedule_time_unchanged():
    assert settings.LEARNING_CONFIG['schedule_time'] == '10:00'


def test_smtp_config_unchanged():
    assert settings.SMTP_CONFIG['port'] == 465
    assert settings.SMTP_CONFIG['host'] == 'smtp.qq.com'
